const { execSync, spawnSync } = require('child_process'); // Use spawnSync for npm install
const fs = require('fs');
const path = require('path');
const readline = require('readline');
const chalk = require('chalk');

let packageName = '';
const configFilePath = path.join(__dirname, '../.localdeploypath');
const scriptParentDir = path.dirname(__dirname); // Get the parent directory of the script
const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

// Icons and color styles
const infoIcon = chalk.blue('ℹ');
const successIcon = chalk.green('✔');
const errorIcon = chalk.red('✖');

function logInfo(message) {
  console.log(`${infoIcon} ${chalk.blue(message)}`);
}

function logSuccess(message) {
  console.log(`${successIcon} ${chalk.green(message)}`);
}

function logError(message) {
  console.error(`${errorIcon} ${chalk.red(message)}`);
}

function loadSavedDestinationPath() {
  let savedDestinationPath = '';
  if (fs.existsSync(configFilePath)) {
    savedDestinationPath = fs.readFileSync(configFilePath, 'utf8').trim();
  }
  return savedDestinationPath;
}

function getDefaultDestinationPath(savedPath) {
  return savedPath || path.resolve('../X3-AutomationTest');
}

function copyPackageToDestination(savedPath, packageName) {
  const defaultDestinationPath = getDefaultDestinationPath(savedPath);
  const pathArgIndex = process.argv.findIndex(arg => arg.startsWith('--destinationPath='));

  if (pathArgIndex === -1) {
    rl.question(
      `Enter the destination folder path (default: ${defaultDestinationPath}): `,
      (destinationPath) => {
        destinationPath = destinationPath.trim();

        if (destinationPath === '') {
          destinationPath = defaultDestinationPath;
        }

        installDependenciesOnDestination(path.resolve(scriptParentDir, destinationPath), packageName);

        rl.close();
        process.exit(0); // Exit the script gracefully
      }
    );
  } else {
    const pathArg = process.argv[pathArgIndex];
    const destinationPath = pathArg.split('=')[1];
    installDependenciesOnDestination(path.resolve(scriptParentDir, destinationPath), packageName);
    process.exit(0); // Exit the script gracefully
  }
}

function installDependenciesOnDestination(destinationPath, packageName) {
  movePackageFileToDestination(path.resolve(scriptParentDir, `./localdeploy/${packageName}`), path.join(destinationPath, packageName));
  updatePackageJson(destinationPath, packageName);
  installDependencies(destinationPath); // Run npm install in the destination folder

  fs.writeFileSync(configFilePath, destinationPath);
}

function movePackageFileToDestination (sourcePath, destinationFilePath) {
  try {
    // Move (cut) the package to the destination folder
    fs.renameSync(sourcePath, destinationFilePath);
    logSuccess(`Package '${packageName}' has been moved to '${destinationFilePath}'.`);
  } catch (error) {
    logError('Error moving package:', error);
  }
}

function movePackageFileToLocalDeploy (sourcePath, destinationFilePath) {
  try {
    fs.renameSync(sourcePath, destinationFilePath);
    logSuccess(`Package '${packageName}' has been moved to local deploy folder.`);
  } catch (error) {
    logError('Error moving package:', error);
  }
}

function updatePackageJson(destinationPath, packageName) {
  const packageJsonPath = path.join(destinationPath, 'package.json');
  const packageJson = JSON.parse(fs.readFileSync(packageJsonPath, 'utf8'));

  backupPackageJson(packageJsonPath, packageJsonPath + '.bak');

  packageJson.dependencies["@sage/x3-automatedtestplatform"] = `file:${packageName}`;

  fs.writeFileSync(packageJsonPath, JSON.stringify(packageJson, null, 2));
}

function backupPackageJson(packageJsonPath, backupPath) {
  try {
    // Read the original package.json file
    const originalPackageJson = fs.readFileSync(packageJsonPath, 'utf8');

    // Write the original package.json content to package.json.bak
    fs.writeFileSync(backupPath, originalPackageJson);

    logSuccess(`Backed up package.json to ${backupPath}`);
  } catch (error) {
    logError('Error backing up package.json:', error.message);
  }
}

function deleteNodeModulesAndLockFile(destinationPath) {
  try {
    // Use spawnSync to delete node_modules and package-lock.json
    logInfo(`Deleting node_modules folder and package-lock.json from ${destinationPath}.`);
    spawnSync('rm', ['-rf', path.join(destinationPath, 'node_modules')]);
    spawnSync('rm', [path.join(destinationPath, 'package-lock.json')]);
    logSuccess('Deleted node_modules folder and package-lock.json.');
  } catch (error) {
    logError('Error deleting node_modules and package-lock.json:', error);
  }
}

function installDependencies(destinationPath) {
  try {
    const originalDir = process.cwd(); // Store the current directory
    process.chdir(destinationPath); // Change to the destination folder

    // Delete node_modules and package-lock.json before running npm install
    deleteNodeModulesAndLockFile(destinationPath);

    logInfo(`Installing dependencies on ${destinationPath}.`);
    // Use spawnSync to run npm install with stdio set to 'inherit'
    const result = spawnSync('npm', ['install'], { stdio: 'inherit', shell: true });

    process.chdir(originalDir); // Change back to the original directory

    if (result.error) {
      logError('Error running npm install:', result.error);
    } else if (result.status !== 0) {
      logError(`npm install exited with code ${result.status}`);
    } else {
      logSuccess('Dependencies installed successfully.');
    }
  } catch (error) {
    logError('Error installing dependencies:', error);
  }
}

function restoreOriginalPackageJson(destinationPath) {
  const packageJsonPath = path.join(destinationPath, 'package.json');
  const packageJsonBackupPath = packageJsonPath + '.bak';

  if (fs.existsSync(packageJsonBackupPath)) {
    const packageJson = JSON.parse(fs.readFileSync(packageJsonBackupPath, 'utf8'));
    fs.writeFileSync(packageJsonPath, JSON.stringify(packageJson, null, 2));
    logSuccess(`Restored the original package.json in '${packageJsonPath}'.`);
    installDependencies(destinationPath); // Run npm install in the destination folder
  } else {
    logError(`Backup file '${packageJsonBackupPath}' not found.`);
  }
}

function deletePackageJsonBackup(destinationPath) {
  const packageJsonBackupPath = path.join(destinationPath, 'package.json.bak');

  if (fs.existsSync(packageJsonBackupPath)) {
    // Delete the package.json.bak file
    fs.unlinkSync(packageJsonBackupPath);
    logSuccess('Deleted package.json.bak file.');
  }
}

function prePublishAndPackage() {
  try {
    logInfo(`Pre-publish process and package generation.`);
    // Use spawnSync to run npm install with stdio set to 'inherit'
    const prepublishResult = spawnSync('npm', ['run prepublish'], { stdio: 'inherit', shell: true });

    if (prepublishResult.error) {
      throw prepublishResult.error; // Throw the error to be caught and logged
    } else if (prepublishResult.status !== 0) {
      throw new Error(`npm run prepublish exited with code ${prepublishResult.status}`);
    }

    execSync('npm pack');

    packageName = execSync('npm pack').toString().trim();

    logSuccess(`Package '${packageName}' has been generated.`);
  } catch (error) {
    logError(`Error generating package: ${error.message}`);
  }
}

const savedPath = loadSavedDestinationPath();

if ('undefined' != typeof process.env.npm_config_rollback) {
  restoreOriginalPackageJson(savedPath);
  deletePackageJsonBackup(savedPath); // Delete the package.json.bak file
  process.exit(0); // Exit the script gracefully
} else {
  prePublishAndPackage();
  movePackageFileToLocalDeploy(path.resolve(scriptParentDir, `${packageName}`), path.resolve(scriptParentDir, `./localdeploy/${packageName}`));
  copyPackageToDestination(savedPath, packageName);
}